-- Every logged set. The id is generated by the app (a UUID) before sending, so if a
-- request is retried (bad gym Wi-Fi), the same set can't be saved twice: the second
-- insert hits the primary key and is ignored. This is what makes offline sync safe.
CREATE TABLE set_logs (
    id          uuid PRIMARY KEY,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    day         date NOT NULL,
    exercise_id text NOT NULL,
    set_index   smallint NOT NULL CHECK (set_index BETWEEN 1 AND 20),
    weight_kg   double precision NOT NULL CHECK (weight_kg BETWEEN 0 AND 1000),
    reps        smallint NOT NULL CHECK (reps BETWEEN 0 AND 100),
    rir         smallint CHECK (rir BETWEEN 0 AND 10),
    note        text NOT NULL DEFAULT '' CHECK (char_length(note) <= 200),
    logged_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX set_logs_user_exercise_idx ON set_logs (user_id, exercise_id, day);
CREATE INDEX set_logs_user_day_idx ON set_logs (user_id, day);

-- One readiness check-in per user per day.
CREATE TABLE readiness_checkins (
    user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    day        date NOT NULL,
    sleep      smallint NOT NULL CHECK (sleep BETWEEN 1 AND 5),
    energy     smallint NOT NULL CHECK (energy BETWEEN 1 AND 5),
    stress     smallint NOT NULL CHECK (stress BETWEEN 1 AND 5),
    sore_areas text[] NOT NULL DEFAULT '{}',
    pain_areas text[] NOT NULL DEFAULT '{}',
    red_flags  text[] NOT NULL DEFAULT '{}',
    score      smallint NOT NULL,
    verdict    text NOT NULL CHECK (verdict IN ('stop', 'rest', 'lighter', 'normal')),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, day)
);
